# Problem Title: Longest Common Prefix Between Two Arrays

# Description:
# You are given two arrays with positive integers, arr1 and arr2.

# A prefix of a positive integer is an integer formed by one or more of its digits, starting from its leftmost digit. For example, 123 is a prefix of the integer 12345, while 234 is not.

# A common prefix of two integers a and b is an integer c, such that c is a prefix of both a and b. For example, 5655359 and 56554 have common prefixes 565 and 5655, while 1223 and 43456 do not have a common prefix.

# You need to find the length of the longest common prefix between all pairs of integers (x, y) such that x belongs to arr1 and y belongs to arr2.

# Return the length of the longest common prefix among all pairs. If no common prefix exists among them, return 0.

# Constraints:
# - 1 <= arr1.length, arr2.length <= 5 * 10^4
# - 1 <= arr1[i], arr2[i] <= 10^8






import time

#OPTIMIZED APPROACH
class Solution2(object):
    def longestCommonPrefix2(self, arr1, arr2):
        n1 = len(arr1)
        n2 = len(arr2)
        prefixes = set()
        for num in arr1:
            s = str(num)
            for i in range(1,len(s)+1):
                prefixes.add(s[:i])
        max_len =0
        for num in arr2:
            s=str(num)
            if len(s) < max_len:
                continue
            for i in range(1,len(s)+1):        
                if s[:i] in prefixes:
                    max_len = max(max_len,i)
                else:
                    break
        
        return max_len

#BRUTE FORCE APPROACH 
class Solution(object):
    def longestCommonPrefix(self, arr1, arr2):
        n1 = len(arr1)
        n2 = len(arr2)
        largest =[0]*((n1*n2))
        d=0      
        for i in range(n1):
            for j in range(n2):
                m1,m2 = len(str(arr1[i])),len(str(arr2[j]))
                a1,a2= str(arr1[i]),str(arr2[j])
                # print(a1," : ",m1,"\t",a2,":",m2)
                pt=min(m1,m2)
                # print(pt)
                s1=[a1[:t] for t in range(1,len(a1)+1)]
                s2=[a2[:t] for t in range(1,len(a2)+1)]
                # print("s1 : " , s1 , " s2 : ",s2 )
                for k in range(pt):
                    if s1[k] == s2[k]:
                        largest[d] = k+1
                    else:
                        break
                # print("largest : " , largest[d])
                d+=1
        max_prefix = max(largest)
        return max_prefix
    


